ART_QUESTIONS: List[Dict[str, Any]] = ART_DATA

ART_BY_ID: Dict[str, Dict[str, Any]] = {item["id"]: item for item in ART_DATA}
ART_BY_SUBMODE: Dict[str, List[Dict[str, Any]]] = {}
for item in ART_DATA:
    ART_BY_SUBMODE.setdefault(item["sub_mode"], []).append(item)
ART_BY_SUB_MODE = ART_BY_SUBMODE


def get_art_item_by_id(item_id: str) -> Optional[Dict[str, Any]]:
    """Retrieve an art trivia item by its unique ID."""
    return ART_BY_ID.get(item_id)


def get_art_question_by_id(question_id: str) -> Optional[Dict[str, Any]]:
    """Alias for get_art_item_by_id."""
    return get_art_item_by_id(question_id)


def get_art_items_by_submode(sub_mode: str) -> List[Dict[str, Any]]:
    """Retrieve all art items for a specific sub-mode."""
    return ART_BY_SUBMODE.get(sub_mode, [])


def get_art_questions_by_submode(sub_mode: str) -> List[Dict[str, Any]]:
    """Alias for get_art_items_by_submode."""
    return get_art_items_by_submode(sub_mode)


def get_random_art_items(count: int = 1, sub_mode: Optional[str] = None) -> List[Dict[str, Any]]:
    """Sample random art items without replacement, optionally filtered by sub-mode."""
    pool = ART_BY_SUBMODE.get(sub_mode, ART_DATA) if sub_mode else ART_DATA
    if not pool:
        return []
    return random.sample(pool, min(count, len(pool)))


def get_random_art_questions(count: int = 1, sub_mode: Optional[str] = None) -> List[Dict[str, Any]]:
    """Alias for get_random_art_items."""
    return get_random_art_items(count=count, sub_mode=sub_mode)


def search_art_by_alias(query: str) -> List[Dict[str, Any]]:
    """Search art items by alias or name match."""
    q = query.lower().strip()
    results = []
    for item in ART_DATA:
        if any(q in alias for alias in item["aliases"]):
            results.append(item)
            continue
        for lang in ["uz", "ru", "en"]:
            if q in item["correct_answer"][lang].lower():
                results.append(item)
                break
    return results
